def choose_move(observation):
    def pt(v, d=None):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return d

    def add_point(container, v):
        q = pt(v)
        if q is not None:
            container.add(q)

    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    sx, sy = pt(observation.get("self_position", (0, 0)), (0, 0))
    ox, oy = pt(observation.get("opponent_position", (sx, sy)), (sx, sy))

    obstacles = set()
    for a in observation.get("obstacles", []):
        add_point(obstacles, a)

    resources = []
    for a in observation.get("resources", []):
        q = pt(a)
        if q is not None:
            resources.append(q)

    own_path = []
    for a in observation.get("self_path", []):
        q = pt(a)
        if q is not None:
            own_path.append(q)

    targets = resources[:]
    if not targets:
        for a in observation.get("targets", []):
            q = pt(a)
            if q is not None:
                targets.append(q)

    # Candidate moves
    moves = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]

    # Opponent proximity hint
    od = abs(sx - ox) + abs(sy - oy)
    chase_mode = False
    flee_mode = False
    if observation.get("mode") == "pursuit_evasion":
        flee_mode = True
    elif observation.get("mode") == "territory_control":
        chase_mode = od <= 4
    elif observation.get("mode") == "resource_collection":
        chase_mode = False
        flee_mode = False
    else:
        flee_mode = od <= 2
        chase_mode = od <= 4 and not resources

    cx = (w - 1) / 2 if w else 0
    cy = (h - 1) / 2 if h else 0

    best_move = (0, 0)
    best_score = -10**18

    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if nx < 0 or ny < 0 or (w and nx >= w) or (h and ny >= h):
            continue
        if (nx, ny) in obstacles:
            continue

        score = 0

        # Resource attraction
        if targets:
            dmin = 10**9
            for tx, ty in targets:
                d = abs(tx - nx) + abs(ty - ny)
                if d < dmin:
                    dmin = d
            score += 40 - 6 * dmin

        # Opponent interaction
        nd = abs(nx - ox) + abs(ny - oy)
        if flee_mode:
            score += 10 * nd
        elif chase_mode:
            score += 12 - 4 * nd

        # Territory/control style shaping: prefer center and mobility
        if w and h:
            score -= abs(nx - cx) + abs(ny - cy)

        # Prefer new squares over own path
        if (nx, ny) in own_path:
            score -= 2
        else:
            score += 2

        # Avoid waiting unless necessary
        if dx == 0 and dy == 0:
            score -= 1

        # Mild bias to keep closer to target when available
        if targets:
            score -= min(abs(nx - tx) + abs(ny - ty) for tx, ty in targets)

        if score > best_score:
            best_score = score
            best_move = (dx, dy)

    return [best_move[0], best_move[1]]

